mapper.select:
select member_seq, board_type, title, content, is_deleted
  from post
 where post_seq = #{targetSeq}

select member_seq, content, is_deleted
  from post_comment
 where post_comment_seq = #{targetSeq}

select count(*)
  from report
 where reporter_seq = #{reporterSeq}
   and target_type  = #{targetType}
   and target_seq   = #{targetSeq}

select *
  from (
        select a.*, rownum rn
          from (
                select report_seq, target_type, target_seq, reason_type, reason_detail,
                       target_content, status, processed_at, created_at
                  from report
                 where reporter_seq = #{reporterSeq}
                 order by report_seq desc
               ) a
         where rownum <= #{endRow}
       )
 where rn > #{startRow}

select *
  from (
        select a.*, rownum rn
          from (
                select rp.report_seq, rp.reporter_seq, rp.reported_seq, rp.target_type, rp.target_seq,
                       rp.reason_type, rp.reason_detail, rp.target_content, rp.status,
                       rp.admin_seq, rp.admin_memo, rp.processed_at, rp.created_at,
                       r.nickname  as reporter_name,
                       d.nickname  as reported_name,
                       d.login_id  as reported_login_id,
                       (select count(*) from report x where x.reported_seq = rp.reported_seq) as reported_count,
                       case when exists (
                                select 1 from blacklist b
                                 where b.member_seq = rp.reported_seq
                                   and 
                            ) then 'Y' else 'N' end as blacklisted
                  from report rp
                  left join member r on r.member_seq = rp.reporter_seq
                  left join member d on d.member_seq = rp.reported_seq
                 where rp.status = #{status}
                 order by rp.report_seq desc
               ) a
         where rownum <= #{endRow}
       )
 where rn > #{startRow}

select *
  from (
        select a.*, rownum rn
          from (
                select b.blacklist_seq, b.member_seq, b.admin_seq, b.report_seq, b.reason,
                       b.start_at, b.end_at, b.released_at, b.released_by, b.created_at,
                       m.nickname  as member_name,
                       m.login_id  as member_login_id,
                       ad.nickname as admin_name,
                       case when  then 'Y' else 'N' end as active
                  from blacklist b
                  left join member m  on m.member_seq  = b.member_seq
                  left join member ad on ad.member_seq = b.admin_seq

                 where 

                 order by b.blacklist_seq desc
               ) a
         where rownum <= #{endRow}
       )
 where rn > #{startRow}
